Object.keys(FALLBACK_EXTRA).forEach(k=>FALLBACK[k]=Object.assign({},I.en,FALLBACK[k]||{},FALLBACK_EXTRA[k]||{}));
const languages=[['auto','Auto detect'],['lv','Latvian'],['en','English'],['ru','Russian'],['es','Spanish'],['fr','French'],['de','German'],['it','Italian'],['pl','Polish'],['uk','Ukrainian'],['lt','Lithuanian'],['et','Estonian'],['da','Danish'],['sv','Swedish'],['no','Norwegian'],['fi','Finnish'],['is','Icelandic'],['fo','Faroese'],['nl','Dutch'],['pt','Portuguese'],['cs','Czech'],['sk','Slovak'],['sl','Slovenian'],['bg','Bulgarian'],['hr','Croatian'],['sr','Serbian'],['ro','Romanian'],['hu','Hungarian'],['el','Greek'],['tr','Turkish'],['ar','Arabic'],['he','Hebrew'],['hi','Hindi'],['zh-CN','Chinese (Simplified)'],['zh-TW','Chinese (Traditional)'],['ja','Japanese'],['ko','Korean'],['id','Indonesian'],['vi','Vietnamese'],['th','Thai'],['af','Afrikaans'],['sq','Albanian'],['am','Amharic'],['hy','Armenian'],['az','Azerbaijani'],['eu','Basque'],['be','Belarusian'],['bn','Bengali'],['bs','Bosnian'],['ca','Catalan'],['fa','Persian'],['gl','Galician'],['ka','Georgian'],['gu','Gujarati'],['is','Icelandic'],['ga','Irish'],['kk','Kazakh'],['ms','Malay'],['mt','Maltese'],['ne','Nepali'],['sw','Swahili'],['ta','Tamil'],['te','Telugu'],['ur','Urdu'],['uz','Uzbek'],['cy','Welsh']];
const t=k=>((I[state.ui]||FALLBACK[state.ui]||I.en)[k] ?? (FALLBACK[state.ui]||{})[k] ?? I.en[k] ?? k);
const opts=(selected,auto=true)=>languages.filter(x=>auto||x[0]!=='auto').map(([c,n])=>`<option value="${c}" ${c===selected?'selected':''}>${n}</option>`).join('');
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function applyTheme(){document.documentElement.dataset.theme=state.theme==='dark'?'dark':'light';document.documentElement.lang=state.ui;document.documentElement.style.setProperty('--font-scale',String(state.fontScale||1));document.querySelector('meta[name="theme-color"]')?.setAttribute('content',state.theme==='dark'?'#10221b':'#f7fafc')}
function uiSwitcher(){const cur=(UI_LANGS.find(x=>x[0]===state.ui)||UI_LANGS[1]);return `<div class="ui-switch"><button class="ui-current" id="uiCurrent" title="${t('language')}"><img class="flag-icon" src="assets/flags/${cur[1]}.svg" alt="${cur[2]}"><span class="code-badge">${cur[2]}</span><span class="ui-chevron" aria-hidden="true"></span></button><div class="ui-menu" id="uiMenu">${UI_LANGS.map(([c,f,abbr,n])=>`<button data-ui="${c}" class="${state.ui===c?'active':''}"><img class="flag-icon" src="assets/flags/${f}.svg" alt="${abbr}"><span>${n}</span><small>${abbr}</small></button>`).join('')}</div></div>`}
function zoomControls(){return `<div class="zoom-controls" title="Text size"><button class="iconbtn zoombtn" id="zoomOut" aria-label="Smaller text">A−</button><button class="zoomread" id="zoomReset" type="button">${Math.round((state.fontScale||1)*100)}%</button><button class="iconbtn zoombtn" id="zoomIn" aria-label="Larger text">A+</button></div>`}
function setFontScale(v){state.fontScale=Math.max(0.9,Math.min(1.45,Math.round(v*100)/100));localStorage.setItem('translate-font-scale',String(state.fontScale));render()}
function render(){applyTheme();const settings=state.tab==='settings';$('#app').innerHTML=`<div class="shell"><header class="topbar"><div class="brand"><img src="assets/icon.svg" alt=""><div>Translate<small>${t('tag')}</small></div></div><nav class="tabs"><button class="tab ${state.tab==='translate'?'active':''}" data-tab="translate">${t('translate')}</button><button class="tab ${state.tab==='live'?'active':''}" data-tab="live">${state.ui==='lv'?'Live mikrofons':'Live microphone'}</button><button class="tab ${state.tab==='media'?'active':''}" data-tab="media">${state.ui==='lv'?'Audio / video':'Audio / video'}</button><button class="tab ${state.tab==='docs'?'active':''}" data-tab="docs">${t('docs')}</button></nav><div class="actions">${uiSwitcher()}${zoomControls()}<button class="iconbtn ${settings?'active':''}" id="settingsJump" title="Settings">⚙</button><button class="iconbtn" id="themeBtn" title="${t('theme')}">${state.theme==='dark'?'☀':'☾'}</button><button class="install-top" id="installTop">↧ <span>${t('pwa')}</span></button></div></header><main class="main">${settings?settingsView():`<section class="intro"><div><h1>${t('title')}</h1><p>${t('intro')}</p></div><div class="badges"><span class="badge">PWA</span><span class="badge">${t('cpanel')}</span><span class="badge">${t('nodatabase')}</span><span class="badge">${t('free')}</span></div></section><div class="privacy-strip"><span>◉ ${t('deviceOnly')}</span><span>⌛ ${state.ui==='lv'?`Servera teksta kešs: ${B.cacheDays||7} dienas`:`Server text cache: ${B.cacheDays||7} days`}</span></div>${translateView()}${liveView()}${docsView()}${installView()}`}<div class="footer">${t('footer')}</div></main>${externalModalView()}</div>`;bind()}
function translateView(){return `<section class="view ${state.tab==='translate'?'active':''}"><div class="card translate-grid"><div class="pane"><div class="langrow"><select class="select" id="fromLang">${opts(state.from,true)}</select></div><textarea id="sourceText" class="text" maxlength="500" spellcheck="true" placeholder="${t('type')}"></textarea><div class="grammar-tools"><button class="btn grammar-btn" id="grammarCheck">✓ LV grammar</button><span class="grammar-note" id="grammarNote">Latvian: garumzīmes, mīkstinājumi, pieturzīmes</span></div><div class="grammar-review" id="grammarReview" hidden><div class="grammar-preview" id="grammarPreview"></div><div class="grammar-issues" id="grammarIssues"></div></div><div class="panefoot"><button class="btn ghost" id="micText">● ${t('speak')}</button><button class="btn ghost" id="clearText">${t('clear')}</button><span class="count" id="sourceCount">0/500</span></div></div><div class="swapcol"><button class="swapbtn" id="swapBtn" title="${t('swap')}">⇄</button></div><div class="pane"><div class="langrow"><select class="select" id="toLang">${opts(state.to,false)}</select><div class="primary-targets">${[['lv','lv','LV'],['en','gb','GB'],['ru','ru','RU']].map(([c,f,abbr])=>`<button class="mini ${state.to===c?'active':''}" data-target="${c}"><img class="flag-icon mini-flag" src="assets/flags/${f}.svg" alt="${abbr}"><small>${abbr}</small></button>`).join('')}</div></div><textarea id="targetText" class="text" readonly placeholder="${t('result')}"></textarea><div class="panefoot"><button class="btn ghost" id="listenBtn">▶ ${t('listen')}</button><button class="btn ghost" id="pauseTtsBtn" disabled>⏸ ${state.ui==='lv'?'Pauze':'Pause'}</button><button class="btn ghost" id="stopTtsBtn" disabled>■ ${state.ui==='lv'?'Stop':'Stop'}</button><button class="btn ghost" id="copyBtn">⧉ ${t('copy')}</button><button class="btn ghost" id="audioBtn">↓ ${t('mp3')}</button></div></div></div><div class="toolbar"><button class="btn primary" id="translateBtn">${t('translate')}</button><button class="btn" id="googleLink">${t('openGoogle')}</button><button class="btn" id="tildeLink">${t('openTilde')}</button><select class="select provider" id="provider"><option value="auto">${t('autoProvider')}</option><option value="google_free">Google free</option><option value="mymemory">MyMemory</option>${B.libreConfigured?'<option value="libretranslate">LibreTranslate</option>':''}${B.microsoftConfigured?'<option value="microsoft">Microsoft Translator</option>':''}${B.geminiConfigured?'<option value="gemini_free">Gemini Free AI</option>':''}</select></div><div class="status" id="translateStatus"></div></section>`}
function liveView(){return `<section class="view ${state.tab==='live'||state.tab==='media'?'active':''}"><div class="mode-explainer ${state.tab==='media'?'media-mode':'live-mode'}"><strong>${state.tab==='media'?(state.ui==='lv'?'Audio / video tulkošana':'Audio / video translation'):(state.ui==='lv'?'Live mikrofona tulkošana':'Live microphone translation')}</strong><span>${state.tab==='media'?(state.ui==='lv'?'Izmanto YouTube/TikTok/Spotify, pārlūka cilnes audio vai lokālu failu. Mikrofons šajā režīmā pēc noklusējuma netiek izmantots.':'Use YouTube/TikTok/Spotify, tab audio, or a local file. The microphone is not used by default in this mode.'):(state.ui==='lv'?'Klausās tikai cilvēka runu caur izvēlēto mikrofonu. Video/pārlūka cilnes audio šajā režīmā netiek izmantots.':'Listens only to spoken voice through the selected microphone. Video/tab audio is not used in this mode.')}</span></div><div class="sectiongrid split-workflows"><div class="card sectioncard mode-live-card" style="${state.tab==='media'?'display:none':''}"><div class="workflow-kicker">🎤 ${state.ui==='lv'?'MIKROFONS':'MICROPHONE'}</div><h2>${state.ui==='lv'?'Live mikrofons — runa apkārt jums':'Live microphone — speech around you'}</h2><p>${state.ui==='lv'?'Izvēlieties runas valodu un tulkojuma valodu, tad nospiediet Sākt klausīties. Šis režīms izmanto tikai mikrofonu.':'Choose spoken language and target language, then press Start listening. This mode uses only the microphone.'}</p><div class="workflow-language-grid"><label><span>${state.ui==='lv'?'No valodas':'From language'}</span><select class="select" id="liveFrom">${opts(state.from,true)}</select></label><div class="lang-arrow">→</div><label><span>${state.ui==='lv'?'Uz valodu':'To language'}</span><select class="select" id="liveTo">${opts(state.to,false)}</select></label></div><div class="controls"><select class="select full" id="liveMode"><option value="conversation" ${state.liveMode==='conversation'?'selected':''}>${state.ui==='lv'?'Saruna / runa':'Conversation / speech'}</option><option value="tv" ${state.liveMode==='tv'?'selected':''}>${state.ui==='lv'?'TV / mūzika fonā':'TV / background music'}</option></select><button class="btn primary full" id="liveToggle">${state.listening?t('stop'):t('start')}</button><button class="btn full" id="speechTest" type="button">🎤 Speech test</button></div><div class="live-status" id="liveStatus">${esc(state.liveStatus||'')}</div><div class="live-interim" id="liveInterim">${esc(state.liveInterim||'')}</div><div class="livebox" id="liveBox">${historyLines()}</div><div class="recording"><button class="btn" id="recordBtn">● ${state.mediaRecorder?.state==='recording'?t('stopRecord'):t('record')}</button><button class="btn" id="downloadRecord" ${state.recordUrl?'':'disabled'}>↓ ${t('recording')}</button><button class="btn" id="downloadTranscript">↓ ${t('transcript')}</button><button class="btn" id="downloadLiveAudio">↓ ${t('translationMp3')}</button></div><div class="voice-panel"><div class="voice-row"><label><span>${t('voice')}</span><select class="select" id="ttsVoice"><option value="">Automatic best free voice — Latvian prefers Microsoft Everita</option></select></label><button class="btn" id="previewVoice">▶ Preview voice</button><button class="btn" id="livePauseTts" disabled>⏸ ${state.ui==='lv'?'Pauze':'Pause'}</button><button class="btn" id="liveStopTts" disabled>■ Stop</button></div><div class="voice-options"><label><span>${state.ui==='lv'?'Kvalitāte':'Quality'}</span><select class="select" id="voiceQuality"><option value="best" ${state.voiceQuality==='best'?'selected':''}>${state.ui==='lv'?'Labākā bezmaksas':'Best free'}</option><option value="online" ${state.voiceQuality==='online'?'selected':''}>Online / Natural</option><option value="local" ${state.voiceQuality==='local'?'selected':''}>${state.ui==='lv'?'Tikai ierīces balss':'Device only'}</option></select></label><label><span>${state.ui==='lv'?'Balss':'Voice'}</span><select class="select" id="voiceGender"><option value="auto" ${state.voiceGender==='auto'?'selected':''}>Auto</option><option value="male" ${state.voiceGender==='male'?'selected':''}>${state.ui==='lv'?'Vīrietis':'Male'}</option><option value="female" ${state.voiceGender==='female'?'selected':''}>${state.ui==='lv'?'Sieviete':'Female'}</option></select></label><label><span>${state.ui==='lv'?'Stils / tembrs':'Style / tone'}</span><select class="select" id="voiceTone"><option value="natural" ${state.voiceTone==='natural'?'selected':''}>${state.ui==='lv'?'Dabiska':'Natural'}</option><option value="warm" ${state.voiceTone==='warm'?'selected':''}>${state.ui==='lv'?'Silta un zemāka':'Warm / deeper'}</option><option value="soft" ${state.voiceTone==='soft'?'selected':''}>${state.ui==='lv'?'Maiga':'Soft / gentle'}</option><option value="clear" ${state.voiceTone==='clear'?'selected':''}>${state.ui==='lv'?'Skaidra / izteiksmīga':'Clear / expressive'}</option></select></label></div><div class="voice-sliders"><div class="levelrow"><span>${state.ui==='lv'?'Ātrums':'Speed'}</span><input id="voiceRate" type="range" min="0.72" max="1.16" value="${state.voiceRate}" step="0.02"><b id="voiceRateLabel">${Math.round(state.voiceRate*100)}%</b></div><div class="levelrow"><span>${state.ui==='lv'?'Tembrs':'Pitch'}</span><input id="voicePitch" type="range" min="0.72" max="1.25" value="${state.voicePitch}" step="0.03"><b id="voicePitchLabel">${Math.round(state.voicePitch*100)}%</b></div><div class="levelrow"><span>Volume</span><input id="ttsVolume" type="range" min="0" max="1" value="0.9" step="0.05"><b id="ttsVolLabel">90%</b></div></div><div class="voice-hint" id="voiceHint"></div></div></div><div class="card sectioncard mode-media-card" style="${state.tab==='live'?'display:none':''}"><div class="workflow-kicker">▶ ${state.ui==='lv'?'MEDIA':'MEDIA'}</div><h2>${state.ui==='lv'?'Audio / video — YouTube, URL vai fails':'Audio / video — YouTube, URL or file'}</h2><p>${state.ui==='lv'?'Šis režīms izmanto media avotu: YouTube subtitrus, pārlūka cilnes audio vai lokāla faila audio. Live mikrofons tiek apturēts automātiski.':'This mode uses the media source: YouTube captions, tab audio, or local file audio. Live microphone listening is stopped automatically.'}</p><div class="media-url-box"><label><span>${state.ui==='lv'?'YouTube / TikTok / Spotify vai cits URL':'YouTube / TikTok / Spotify or other URL'}</span><div class="media-url-row"><input class="select" id="mediaUrl" type="url" placeholder="https://…" value="${esc(state.remoteMediaUrl||'')}"><button class="btn" id="mediaUrlLoad" type="button">${state.ui==='lv'?'Ielādēt URL':'Load URL'}</button></div></label><div class="help">${state.ui==='lv'?'Playeris tiek ielādēts no oriģinālā servisa. Audio netiek saglabāts serverī.':'The player loads from the original service. Audio is not stored on the server.'}</div></div><div class="media-drop upload-drop" id="mediaDrop" tabindex="0"><input id="mediaFile" class="file-input-hidden" type="file" accept="audio/*,video/*"><button class="btn upload-choose" id="mediaChoose" type="button">Choose audio / video</button><div class="upload-title">Drag & drop audio or video here</div><div class="help">MP3 · M4A · WAV · MP4 · WebM</div></div><div id="mediaPlayer"></div><div class="media-accuracy"><div class="workflow-language-grid media-language-grid"><label><span>${state.ui==='lv'?'No valodas / video valoda':'From language / video language'}</span><select class="select" id="mediaFrom">${opts(state.mediaFrom,false)}</select></label><div class="lang-arrow">→</div><label><span>${state.ui==='lv'?'Uz valodu':'To language'}</span><select class="select" id="mediaTo">${opts(state.mediaTo,false)}</select></label></div><label><span>${state.ui==='lv'?'Audio avots':'Audio source'}</span><select class="select" id="mediaSource"><option value="tab" ${state.mediaSource==='tab'?'selected':''}>${state.ui==='lv'?'Video / pārlūka cilnes audio — ieteicams YouTube':'Video / tab audio — recommended for YouTube'}</option><option value="local" ${state.mediaSource==='local'?'selected':''}>${state.ui==='lv'?'Lokālais augšupielādētais fails':'Local uploaded file'}</option><option value="mic" ${state.mediaSource==='mic'?'selected':''}>${state.ui==='lv'?'Mikrofons — tikai rezerves variants':'Microphone — fallback only'}</option></select></label><label><span>${state.ui==='lv'?'Atpazīšanas kvalitāte':'Recognition quality'}</span><select class="select" id="mediaAccuracy"><option value="captions" ${state.mediaAccuracy==='captions'?'selected':''}>${state.ui==='lv'?'1. YouTube subtitri — ātrākais':'1. YouTube captions — fastest'}</option><option value="whisper" ${state.mediaAccuracy==='whisper'?'selected':''}>${B.geminiConfigured?(state.ui==='lv'?'2. Augsta kvalitāte — Free AI audio + Whisper Tiny':'2. High quality — Free AI audio + Whisper Tiny'):(state.ui==='lv'?'2. Audio transkripcija — Whisper Tiny':'2. Audio transcription — Whisper Tiny')}</option><option value="browser" ${state.mediaAccuracy==='browser'?'selected':''}>${state.ui==='lv'?'3. Mikrofons — rezerves režīms':'3. Microphone — fallback'}</option></select></label><label id="youtubeTrackWrap" style="${state.remoteMediaProvider==='YouTube'?'':'display:none'}"><span>${state.ui==='lv'?'YouTube subtitru celiņš':'YouTube subtitle track'}</span><select class="select" id="youtubeCaptionTrack"><option value="auto">${state.ui==='lv'?'Auto — labākais pieejamais':'Auto — best available'}</option>${(state.youtubeCaptionTracks||[]).map(tr=>`<option value="${tr.index}" ${String(state.youtubeCaptionTrack)===String(tr.index)?'selected':''}>${esc(tr.name||tr.language||'Track')} · ${esc(tr.language||'')} ${tr.auto?'(auto-generated)':'(manual)'}</option>`).join('')}</select></label><button class="btn caption-load-btn" id="loadCaptionBtn" type="button" style="${state.remoteMediaProvider==='YouTube'?'':'display:none'}">CC ${state.ui==='lv'?'Ielādēt un tulkot izvēlētos subtitrus':'Load & translate selected subtitles'}</button><div class="help" id="mediaSourceHelp">${state.ui==='lv'?'YouTube subtitri ir ātrākais variants, ja tie ir pieejami. Audio režīmā ar ieslēgtu Free AI Assist vispirms izmantojam augstākas kvalitātes AI audio transkripciju un automātiski krītam atpakaļ uz lokālo Whisper Tiny.':'YouTube captions are fastest when available. In audio mode, if Free AI Assist is configured, higher-quality AI audio transcription is tried first with automatic local Whisper Tiny fallback.'}</div></div><div id="remoteMediaStatus" class="remote-media-status"></div><div class="remote-transcript-wrap"><div class="remote-transcript-head"><strong>${state.ui==='lv'?'Atpazītais teksts':'Recognized transcript'}</strong><button class="btn tiny" id="clearRemoteTranscript" type="button">${state.ui==='lv'?'Notīrīt':'Clear'}</button></div><div class="remote-transcript" id="remoteTranscript">${esc(state.remoteTranscript||'')}<span class="remote-interim" id="remoteInterim">${esc(state.remoteInterim||'')}</span></div></div><div class="remote-transcript-wrap media-translation-wrap"><div class="remote-transcript-head"><strong>${state.ui==='lv'?'Tulkojums':'Translation'}</strong><span class="help">${state.ui==='lv'?'Atjaunojas, kamēr video turpinās':'Updates while the media continues'}</span></div><div class="remote-transcript media-translation-text" id="remoteTranslation">${esc(state.mediaTranslationText||'')}</div></div><div class="media-finalize-row"><label class="media-finalize-check"><input type="checkbox" id="mediaFinalizeOnStop" ${state.mediaFinalizeOnStop?'checked':''}> <span>${state.ui==='lv'?'Pēc Stop vēlreiz pārbaudīt visu ierakstu un aizpildīt izlaistos teikumus':'After Stop, re-check the full recording and fill missed sentences'}</span></label><button class="btn" id="finalizeMediaRecording" ${state.mediaRecordBlob?'':'disabled'}>${state.ui==='lv'?'✓ Pabeigt no ieraksta':'✓ Complete from recording'}</button></div><div class="media-downloads"><button class="btn" id="downloadMediaTranscript" disabled>↓ ${state.ui==='lv'?'Transkripts TXT':'Transcript TXT'}</button><button class="btn" id="downloadMediaBilingual" disabled>↓ ${state.ui==='lv'?'Tulkojums TXT':'Translation TXT'}</button><button class="btn" id="downloadMediaRecording" disabled>↓ ${state.ui==='lv'?'Audio ieraksts':'Audio recording'}</button><button class="btn" id="downloadMediaMp3" disabled>↓ ${state.ui==='lv'?'Tulkojuma MP3':'Translation MP3'}</button></div><div class="levelrow"><span>${t('originalMedia')}</span><input id="mediaVolume" type="range" min="0" max="1" value="0.25" step="0.05"><b id="mediaVolLabel">25%</b></div><div class="media-actions"><button class="btn full" id="mediaRecognize" disabled>${t('mediaTranslate')}</button><button class="btn primary full" id="captureTabAudio" type="button">${state.remoteCapturing?(state.ui==='lv'?'Apturēt VIDEO audio':'Stop VIDEO audio'):(state.mediaAccuracy==='captions'?(state.ui==='lv'?'Ielādēt YouTube subtitrus':'Load YouTube captions'):(state.ui==='lv'?'Sākt VIDEO audio transkripciju':'Start VIDEO audio transcription'))}</button></div></div></div>${historyView()}</section>`}
function docsView(){return `<section class="view ${state.tab==='docs'?'active':''}"><div class="sectiongrid"><div class="card sectioncard"><h2>${t('docTitle')}</h2><p>${t('docText')}</p><div class="docdrop upload-drop" id="docDrop" tabindex="0"><input type="file" class="file-input-hidden" id="docFile" accept=".txt,.md,.csv,.json,.html,.htm,.srt,.vtt,.docx,.pdf"><button class="btn upload-choose" id="docChoose" type="button">Choose document</button><div class="upload-title">${t('chooseDoc')}</div><div class="docmeta" id="docMeta">TXT · DOCX · PDF · SRT · VTT · CSV · HTML</div></div><div class="controls doccontrols"><select class="select" id="docFrom">${opts(state.from,true)}</select><select class="select" id="docTo">${opts(state.to,false)}</select><button class="btn primary full" id="docTranslate" disabled>${t('translateDoc')}</button></div><div class="progress"><i id="docProgress"></i></div></div><div class="card sectioncard"><h2>${t('translatedDoc')}</h2><textarea class="text docoutput" id="docOutput" readonly></textarea><div class="recording"><button class="btn" id="downloadTxt" disabled>↓ ${t('downloadTxt')}</button><button class="btn" id="downloadHtml" disabled>↓ ${t('downloadHtml')}</button><button class="btn" id="docListen" disabled>▶ ${t('listenDoc')}</button><button class="btn" id="docPause" disabled>⏸ ${state.ui==='lv'?'Pauze':'Pause'}</button><button class="btn" id="docStop" disabled>■ Stop</button><button class="btn" id="docAudio" disabled>↓ ${t('audioDoc')}</button></div></div></div></section>`}
function installView(){const items=[['android','android','Android',t('androidGuide')],['ios','apple','iPhone / iPad',t('iosGuide')],['windows','windows','Windows',t('winGuide')],['mac','apple','macOS',t('macGuide')],['linux','linux','Linux',t('linuxGuide')]];return `<section class="install-card card" id="installCard"><div><h2>${t('installTitle')}</h2><p>${t('installText')}</p></div><div class="install-grid">${items.map(([id,ico,name,guide])=>`<button class="platform" data-platform="${id}"><span class="platform-icon-wrap"><img class="platform-icon" src="assets/platforms/${ico}.svg" alt=""></span><span>${name}<small>${guide}</small></span><em>${state.installed?t('installed'):t('install')}</em></button>`).join('')}</div><div class="install-help" id="installHelp"></div></section>`}
function audioSetupView(){return `<section class="install-card card" id="audioSettings"><div><h2>🎙 Microphone, PC & Bluetooth audio</h2><p>Choose your phone, laptop, webcam, USB or headset microphone. For quiet speech, use Quiet speech and increase Input boost until normal talking reaches the green area.</p></div><div class="audio-settings-grid"><label>Microphone / input<select class="select" id="audioInput"><option value="">System default</option></select></label><label>Headphones / output<select class="select" id="audioOutput"><option value="">System default</option></select></label><label>Microphone profile<select class="select" id="micProfile"><option value="quiet">Quiet speech / sensitive</option><option value="normal">Normal room</option><option value="noisy">Noisy room</option><option value="headset">PC / USB headset</option><option value="raw">Raw / studio mic</option></select></label><label>Translated audio channel<select class="select" id="audioPan"><option value="both">Both / stereo</option><option value="left">Left ear only</option><option value="right">Right ear only</option></select></label><label>Input boost <span id="micGainLabel">${state.micGain.toFixed(1)}×</span><input type="range" id="micGain" min="1" max="3" step="0.1" value="${state.micGain}"></label><label>Voice sensitivity <span id="micSensitivityLabel">${Math.round(state.micSensitivity*100)}%</span><input type="range" id="micSensitivity" min="0.08" max="0.50" step="0.01" value="${state.micSensitivity}"></label><label class="checkrow"><input type="checkbox" id="micNoise" ${state.micNoise?'checked':''}> Noise suppression</label><label class="checkrow"><input type="checkbox" id="micEcho" ${state.micEcho?'checked':''}> Echo cancellation</label><label class="checkrow"><input type="checkbox" id="micAgc" ${state.micAgc?'checked':''}> Automatic gain control</label><div class="mic-meter-wrap"><div class="mic-meter-head"><span>Live microphone level</span><strong id="micLevelText">Not testing</strong></div><div class="mic-meter"><i id="micLevelBar"></i><b class="mic-threshold" id="micThreshold"></b></div></div><div class="settings-actions mic-actions"><button class="btn primary" id="testMic">Test microphone</button><button class="btn" id="stopMicTest" disabled>Stop test</button><button class="btn" id="refreshAudio">↻ Detect PC / audio devices</button></div></div><div class="help">PC tip: Windows/macOS/Linux browsers can list built-in, webcam, USB and headset microphones after microphone permission is granted. For browser speech recognition, the operating system's active/default microphone may still be used by the browser; choose the same mic as default in your PC sound settings for the most reliable live translation.</div></section>`}
function adminSettingsView(){return `<section class="install-card card" id="adminSettings"><div><h2>⚙ Security, cache & free AI</h2><p>${state.ui==='lv'?'Privātam app var glabāt tikai teksta/transcript tulkojumu cache ilgāk. Audio/video faili serverī netiek glabāti. Gemini tiek lietots tikai tad, ja to ieslēdzat un pievienojat savu Free Tier API atslēgu.':'For this private app, translation/transcript text can be cached longer. Audio/video files are not stored on the server. Gemini is used only when enabled with your own Free Tier API key.'}</p></div><div class="settings-grid"><label class="checkrow"><input type="checkbox" id="hcEnabled"> Enable hCaptcha on login</label><label>hCaptcha site key<input class="select" id="hcSitekey" autocomplete="off" placeholder="Site key"></label><label>hCaptcha secret<input class="select" id="hcSecret" type="password" autocomplete="new-password" placeholder="Leave blank to keep existing secret"></label><label>${state.ui==='lv'?'Teksta cache ilgums':'Text cache retention'}<select class="select" id="cacheDays"><option value="1">1 day</option><option value="3">3 days</option><option value="7">7 days</option><option value="14">14 days</option><option value="30">30 days</option></select></label><label class="checkrow"><input type="checkbox" id="freeAiEnabled"> ${state.ui==='lv'?'Ieslēgt Free AI Assist (Gemini)':'Enable Free AI Assist (Gemini)'}</label><label>Gemini Free Tier API key<input class="select" id="geminiKey" type="password" autocomplete="new-password" placeholder="Leave blank to keep existing key"></label><label>Gemini model<select class="select" id="geminiModel"><option value="gemini-2.5-flash">Gemini 2.5 Flash — audio + higher quality</option><option value="gemini-2.5-flash-lite">Gemini 2.5 Flash-Lite — lighter quota use</option></select></label><div class="help">${state.ui==='lv'?'App pats neaktivizē maksas plānu. Izmantojiet Google AI Studio Free Tier atslēgu; ja free kvota beidzas, app atgriežas pie pārējiem bezmaksas tulkotājiem.':'The app does not activate a paid plan. Use a Google AI Studio Free Tier key; when free quota is exhausted, the app falls back to the other free translators.'}</div><div class="settings-actions"><button class="btn primary" id="saveSettings">Save settings</button><button class="btn" id="clearCache">Clean server cache</button><a class="btn" href="?logout=1">Log out</a></div><div class="status" id="settingsStatus"></div></div></section>`}

function settingsView(){return `<section class="settings-page"><div class="settings-page-head"><button class="btn" id="settingsBack" type="button">← Back</button><div><h1>Settings</h1><p>Audio devices, microphone sensitivity, Bluetooth routing, security and server cache.</p></div></div>${audioSetupView()}${adminSettingsView()}</section>`}
function externalModalView(){return `<div class="modal-backdrop" id="externalModal" hidden><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="externalModalTitle"><button class="modal-close" id="externalModalClose" type="button" aria-label="Close">×</button><div class="modal-brand" id="externalModalBrand"></div><h2 id="externalModalTitle">Open translation service</h2><p id="externalModalText"></p><div class="modal-actions"><button class="btn" id="externalModalCancel" type="button">Cancel</button><a class="btn primary" id="externalModalOpen" href="#" target="_blank" rel="noopener noreferrer">Open in new tab ↗</a></div></div></div>`}
function openExternalModal(kind,url){const modal=$('#externalModal');if(!modal)return;const isGoogle=kind==='google';$('#externalModalBrand').textContent=isGoogle?'Google Translate':'Tilde Translate';$('#externalModalTitle').textContent=isGoogle?t('openGoogle'):t('openTilde');$('#externalModalText').textContent=isGoogle?'The current source and target languages will be opened in Google Translate in a new browser tab.':'Tilde Translate will open in a new browser tab. You can continue using this app here.';$('#externalModalOpen').href=url;modal.hidden=false;document.body.classList.add('modal-open')}
function closeExternalModal(){const modal=$('#externalModal');if(modal)modal.hidden=true;document.body.classList.remove('modal-open')}
function historyLines(){if(!state.history.length)return `<p class="empty">${t('noHistory')}</p>`;return state.history.slice(-8).reverse().map(h=>`<div class="liveitem"><span>${esc(h.original)}</span><b>→</b><strong>${esc(h.translated)}</strong></div>`).join('')}
function historyView(){return `<div class="card history"><h3>${t('history')}</h3>${state.history.slice(-8).reverse().map(h=>`<div class="historyitem"><time>${new Date(h.time).toLocaleTimeString()}</time><p>${esc(h.original)}<br><strong>${esc(h.translated)}</strong></p><button data-del="${h.time}">×</button></div>`).join('')||`<p class="empty">${t('noHistory')}</p>`}</div>`}
function bind(){
 $$('.tab').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render()});
 $('#themeBtn').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('translate-theme',state.theme);render()};
 $('#uiCurrent').onclick=e=>{e.stopPropagation();$('#uiMenu').classList.toggle('open')};$$('[data-ui]').forEach(b=>b.onclick=()=>{state.ui=b.dataset.ui;localStorage.setItem('translate-ui',state.ui);render()});document.onclick=()=>$('#uiMenu')?.classList.remove('open');
 const zIn=$('#zoomIn'),zOut=$('#zoomOut'),zReset=$('#zoomReset');if(zIn)zIn.onclick=()=>setFontScale((state.fontScale||1)+0.1);if(zOut)zOut.onclick=()=>setFontScale((state.fontScale||1)-0.1);if(zReset)zReset.onclick=()=>setFontScale(1);$('#settingsJump').onclick=()=>{state.tab=state.tab==='settings'?'translate':'settings';render()};$('#installTop').onclick=()=>installFor('auto');$$('[data-platform]').forEach(b=>b.onclick=()=>installFor(b.dataset.platform));const sb=$('#settingsBack');if(sb)sb.onclick=()=>{state.tab='translate';render()};const mc=$('#externalModalClose'),mcan=$('#externalModalCancel'),mb=$('#externalModal');if(mc)mc.onclick=closeExternalModal;if(mcan)mcan.onclick=closeExternalModal;if(mb)mb.onclick=e=>{if(e.target===mb)closeExternalModal()};document.onkeydown=e=>{if(e.key==='Escape')closeExternalModal()};
 if($('#fromLang'))bindTranslate();if($('#liveFrom'))bindLive();if($('#docFile'))bindDocs();if($('#audioInput'))bindAudioSettings();if($('#adminSettings'))bindAdminSettings();$$('[data-del]').forEach(b=>b.onclick=()=>{state.history=state.history.filter(h=>String(h.time)!==b.dataset.del);saveHistory();render()});
}
function bindTranslate(){const src=$('#sourceText'),dst=$('#targetText');src.lang=(state.from==='lv'||state.from==='auto')?'lv':'en';$('#fromLang').onchange=e=>{state.from=e.target.value;src.lang=state.from==='lv'?'lv':state.from==='auto'?'lv':state.from};$('#toLang').onchange=e=>setTarget(e.target.value);$$('[data-target]').forEach(b=>b.onclick=()=>{setTarget(b.dataset.target);render()});src.oninput=()=>{$('#sourceCount').textContent=src.value.length+'/500';if(!$('#grammarReview')?.hidden)runLatvianGrammar(src.value)};$('#clearText').onclick=()=>{src.value='';dst.value='';$('#sourceCount').textContent='0/500';const gr=$('#grammarReview');if(gr)gr.hidden=true};$('#grammarCheck').onclick=()=>runLatvianGrammar(src.value);$('#swapBtn').onclick=()=>{if(state.from==='auto')state.from=state.to;else [state.from,state.to]=[state.to,state.from];render()};$('#provider').value=state.provider;$('#provider').onchange=e=>{state.provider=e.target.value;localStorage.setItem('translate-provider',state.provider)};$('#translateBtn').onclick=async()=>{if(!src.value.trim())return;if(src.value.length>500){status(state.ui==='lv'?'Teksta tulkošanai maksimums ir 500 simboli.':'Text translation is limited to 500 characters.',true);return}status(state.ui==='lv'?'Tulkoju…':'Translating…');try{const j=await translateSingle(src.value,state.from,state.to,state.provider);dst.value=j.translated;status(j.cached?`Cached · ${B.cacheDays||7}d`:'✓ '+j.provider)}catch(e){status(e.message,true)}};$('#listenBtn').onclick=()=>speak(dst.value,state.to);const pt=$('#pauseTtsBtn'),stp=$('#stopTtsBtn');if(pt)pt.onclick=toggleTtsPause;if(stp)stp.onclick=stopTtsPlayback;$('#copyBtn').onclick=()=>navigator.clipboard?.writeText(dst.value);$('#audioBtn').onclick=()=>downloadTts(dst.value,state.to);$('#micText').onclick=()=>oneShotRecognition(state.from,x=>{src.value=x;src.dispatchEvent(new Event('input'))});$('#googleLink').onclick=()=>openExternalModal('google',`https://translate.google.com/?sl=${encodeURIComponent(state.from)}&tl=${encodeURIComponent(state.to)}&text=${encodeURIComponent(src.value)}`);$('#tildeLink').onclick=()=>openExternalModal('tilde','https://tilde.ai/lv/translate/tilde-machine-translation/')}
const LV_WORD_FIXES={
'garumzimes':'garumzīmes','pieturzimes':'pieturzīmes','mikstinajumi':'mīkstinājumi','latviesu':'latviešu','latviesiem':'latviešiem','latviesi':'latvieši','latvija':'Latvija','latvijas':'Latvijas','ludzu':'lūdzu','butu':'būtu','bija':'bija','bus':'būs','mes':'mēs','jus':'jūs','vini':'viņi','vinas':'viņas','vins':'viņš','vina':'viņa','saja':'šajā','sis':'šis','si':'šī','seit':'šeit','sodien':'šodien','rit':'rīt','vel':'vēl','pec':'pēc','pirms':'pirms','kadreiz':'kādreiz','kapec':'kāpēc','tadel':'tādēļ','tapat':'tāpat','tacu':'taču','tomer':'tomēr','svarigi':'svarīgi','pareizi':'pareizi','nepareizi':'nepareizi','vardu':'vārdu','vardi':'vārdi','vards':'vārds','teksta':'tekstā','teksts':'teksts','valoda':'valoda','valodas':'valodas','tulkosana':'tulkošana','tulkot':'tulkot','tulkojums':'tulkojums','ierice':'ierīce','ierices':'ierīces','iespeja':'iespēja','iespejas':'iespējas','izveleties':'izvēlēties','izvele':'izvēle','parbaude':'pārbaude','parbaudit':'pārbaudīt','labot':'labot','kluda':'kļūda','kludas':'kļūdas','rakstit':'rakstīt','rakstiba':'rakstība','pareizrakstiba':'pareizrakstība','teikums':'teikums','teikuma':'teikuma','skaisti':'skaisti','jauks':'jauks','jauku':'jauku','dienu':'dienu','paldies':'paldies','sveiki':'sveiki','atvainojiet':'atvainojiet','iespejams':'iespējams','vispar':'vispār','vairak':'vairāk','mazak':'mazāk','atrak':'ātrāk','lenak':'lēnāk','labs':'labs','labi':'labi','drosi':'droši','vienmer':'vienmēr','ari':'arī','tikai':'tikai','ne':'ne','ja':'ja','jā':'jā','vai':'vai','ka':'ka','kā':'kā','kur':'kur','tur':'tur','nav':'nav','esmu':'esmu','esi':'esi'};
function lvGrammarMatches(text){const out=[];let m;const wordRe=/\b[A-Za-zĀ-ž]+\b/g;while((m=wordRe.exec(text))){const raw=m[0],low=raw.toLocaleLowerCase('lv-LV'),fix=LV_WORD_FIXES[low];if(fix&&fix.toLocaleLowerCase('lv-LV')!==low){let repl=fix;if(raw[0]===raw[0].toUpperCase())repl=repl.charAt(0).toUpperCase()+repl.slice(1);out.push({offset:m.index,length:raw.length,repl,type:'spelling',msg:'Iespējama garumzīmes, mīkstinājuma vai pareizrakstības kļūda.'})}}
 const rules=[
  {re:/\s+([,.;:!?])/g,make:x=>({offset:x.index,length:x[0].length,repl:x[1],type:'punct',msg:'Pirms pieturzīmes parasti neliek atstarpi.'})},
  {re:/([,;:!?])(\S)/g,make:x=>({offset:x.index,length:x[0].length,repl:x[1]+' '+x[2],type:'punct',msg:'Pēc pieturzīmes parasti vajadzīga atstarpe.'})},
  {re:/([!?.,])\1{1,}/g,make:x=>({offset:x.index,length:x[0].length,repl:x[1],type:'punct',msg:'Atkārtota pieturzīme.'})},
  {re:/ {2,}/g,make:x=>({offset:x.index,length:x[0].length,repl:' ',type:'space',msg:'Vairākas atstarpes pēc kārtas.'})}
 ];
 for(const r of rules){r.re.lastIndex=0;while((m=r.re.exec(text)))out.push(r.make(m))}
 const sentRe=/(^|[.!?]\s+)([a-zāčēģīķļņšūž])/g;while((m=sentRe.exec(text))){const pos=m.index+m[1].length;out.push({offset:pos,length:1,repl:m[2].toLocaleUpperCase('lv-LV'),type:'case',msg:'Teikumu parasti sāk ar lielo burtu.'})}
 return out.sort((a,b)=>a.offset-b.offset||a.length-b.length).filter((x,i,a)=>!i||x.offset!==a[i-1].offset||x.length!==a[i-1].length);
}
function grammarMarkedHtml(text,matches){let html='',p=0;for(const x of matches){if(x.offset<p)continue;html+=esc(text.slice(p,x.offset));html+=`<span class="grammar-error" title="${esc(x.msg)}">${esc(text.slice(x.offset,x.offset+x.length))}</span>`;p=x.offset+x.length}return html+esc(text.slice(p)).replace(/\n/g,'<br>')}
function runLatvianGrammar(text){const review=$('#grammarReview'),preview=$('#grammarPreview'),issues=$('#grammarIssues'),note=$('#grammarNote');if(!review||!preview||!issues)return;review.hidden=false;if(!text.trim()){preview.textContent='';issues.innerHTML='<span class="grammar-ok">Ievadiet tekstu pārbaudei.</span>';return}const matches=lvGrammarMatches(text);preview.innerHTML=grammarMarkedHtml(text,matches);if(!matches.length){issues.innerHTML='<span class="grammar-ok">✓ Acīmredzamas kļūdas netika atrastas.</span>';if(note)note.textContent='✓ Latvian check';return}if(note)note.textContent=`${matches.length} iespējam${matches.length===1?'a kļūda':'as kļūdas'}`;issues.innerHTML=matches.slice(0,30).map((x,i)=>`<button class="grammar-fix" data-gfix="${i}"><span>${esc(x.msg)}</span><b>${esc(text.slice(x.offset,x.offset+x.length))} → ${esc(x.repl)}</b></button>`).join('')+`<button class="btn primary grammar-fix-all" id="grammarFixAll">Labot visu</button>`;$$('[data-gfix]').forEach(b=>b.onclick=()=>applyGrammarFix(matches[+b.dataset.gfix]));$('#grammarFixAll').onclick=()=>applyAllGrammarFixes(matches)}
function applyGrammarFix(x){const src=$('#sourceText');if(!src)return;src.value=src.value.slice(0,x.offset)+x.repl+src.value.slice(x.offset+x.length);src.dispatchEvent(new Event('input'))}
function applyAllGrammarFixes(matches){const src=$('#sourceText');if(!src)return;let text=src.value;[...matches].sort((a,b)=>b.offset-a.offset).forEach(x=>{text=text.slice(0,x.offset)+x.repl+text.slice(x.offset+x.length)});src.value=text;src.dispatchEvent(new Event('input'))}

function setTarget(v){state.to=v;localStorage.setItem('translate-target',v)}
function status(s,bad=false){const e=$('#translateStatus');if(e){e.textContent=s;e.classList.toggle('bad',bad)}}
